from collections import deque
G=[[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
R,C=len(G),len(G[0]); seen=set(); comps=[]
for i in range(R):
 for j in range(C):
  if G[i][j]==0 and (i,j) not in seen:
   q=[(i,j)]; seen.add((i,j)); comp=[]
   while q:
    x,y=q.pop(); comp.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=x+dx,y+dy
     if 0<=a<R and 0<=b<C and G[a][b]==0 and (a,b) not in seen:
      seen.add((a,b)); q.append((a,b))
   comps.append(comp)
